std::shared_ptr<const PlaybackPlan> playbackPlan(const QString& group,const QJsonArray& strokes,const std::vector<nativeink::StrokeTiming>& timing,PlaybackConfig config){nativeink::checked(strokes,"tom_illustration");product::require((timing.empty()||timing.size()==std::size_t(strokes.size()))&&std::isfinite(config.pixelsPerSecond)&&config.pixelsPerSecond>=100&&config.pixelsPerSecond<=3000&&std::isfinite(config.accelerationTravel)&&config.accelerationTravel>=1000&&config.minimumMs>=100&&config.maximumMs>=config.minimumMs&&config.maximumMs<=120000&&config.intervalMs>=20&&config.intervalMs<=100&&config.pointBudget>=16&&config.pointBudget<=512,"tom-playback-config");auto plan=std::make_shared<PlaybackPlan>();plan->group=group;plan->bounds=nativeink::bounds(strokes);plan->config=config;plan->strokes.reserve(strokes.size());double effort=0;std::size_t source=0;for(auto value:strokes){auto s=value.toObject();QJsonArray paths{s["points"].toArray()};for(auto hole:s["holes"].toArray())paths.append(hole);for(int pathIndex=0;pathIndex<paths.size();++pathIndex){auto path=paths[pathIndex];PlaybackStroke stroke;stroke.source=unsigned(source);if(s["shape"]=="polygon"&&pathIndex+1==paths.size())stroke.fill=std::make_shared<const QJsonObject>(s);stroke.style=styled::parseStyle(s["style"].toObject());stroke.rate=.952+double(plan->strokes.size()%13)*.008;stroke.points.reserve(path.toArray().size()+1);for(auto v:path.toArray()){auto p=v.toArray();stroke.points.push_back({p[0].toDouble(),p[1].toDouble()});}if(s["shape"]=="polygon"&&stroke.points.size()>2)stroke.points.push_back(stroke.points.front());for(std::size_t n=1;n<stroke.points.size();++n)stroke.travel+=std::hypot(stroke.points[n].x-stroke.points[n-1].x,stroke.points[n].y-stroke.points[n-1].y);const double complexity=timing.empty()?1:timing[source].complexity;product::require(std::isfinite(complexity)&&complexity>=1&&complexity<=4&&(timing.empty()||timing[source].pauseAfterMs<=1000),"tom-playback-cadence");stroke.durationMs=(stroke.travel*complexity+10)/config.pixelsPerSecond*1000/stroke.rate;stroke.pauseAfterMs=pathIndex+1==paths.size()?(timing.empty()?8:timing[source].pauseAfterMs):8;plan->travel+=stroke.travel;effort+=stroke.travel*complexity+10;plan->strokes.push_back(std::move(stroke));}++source;}const double acceleration=1+effort/config.accelerationTravel;double total=0;for(auto& stroke:plan->strokes){stroke.durationMs/=acceleration;stroke.pauseAfterMs/=std::sqrt(acceleration);total+=stroke.durationMs+stroke.pauseAfterMs;}const double scale=total>0?std::clamp(total,config.minimumMs,config.maximumMs)/total:1;for(auto& stroke:plan->strokes){stroke.durationMs*=scale;stroke.pauseAfterMs*=scale;}plan->durationMs=total*scale;return plan;}
bool StrokePlayback::extend(std::shared_ptr<const PlaybackPlan> next){if(!next)return false;if(!plan_){start(std::move(next));return true;}if(plan_->group!=next->group||next->strokes.size()<plan_->strokes.size())return false;for(std::size_t n=0;n<plan_->strokes.size();++n){const auto&a=plan_->strokes[n];const auto&b=next->strokes[n];if(a.style.tool!=b.style.tool||a.style.width!=b.style.width||a.style.color!=b.style.color||a.points.size()!=b.points.size())return false;for(std::size_t p=0;p<a.points.size();++p)if(a.points[p].x!=b.points[p].x||a.points[p].y!=b.points[p].y)return false;}plan_=std::move(next);return true;}
QJsonArray StrokePlayback::visibleStrokes()const{QJsonArray result;if(!plan_)return result;QSet<unsigned> filled;for(std::size_t n=0;n<stroke_&&n<plan_->strokes.size();++n)if(plan_->strokes[n].fill)filled.insert(plan_->strokes[n].source);for(std::size_t n=0;n<plan_->strokes.size()&&n<=stroke_;++n){const auto& stroke=plan_->strokes[n];if(filled.contains(stroke.source)){if(stroke.fill)result.append(*stroke.fill);continue;}QJsonArray points;if(n<stroke_)for(const auto&p:stroke.points)points.append(QJsonArray{p.x,p.y});else if(begun_){for(std::size_t p=0;p<point_&&p<stroke.points.size();++p)points.append(QJsonArray{stroke.points[p].x,stroke.points[p].y});points.append(QJsonArray{cursor_.x,cursor_.y});}if(!points.isEmpty())result.append(QJsonObject{{"style",styled::jsonStyle(stroke.style)},{"points",points}});}return result;}
void StrokePlayback::suspend(PlaybackTarget& canvas)noexcept{if(penOpen_)canvas.playEnd();penOpen_=false;next_=last_={};}
bool StrokePlayback::tick(PlaybackTarget& canvas,std::chrono::steady_clock::time_point now){if(!active())return false;if(canvas.contact()||canvas.pending()){next_=last_={};return false;}if(now<next_)return false;const auto interval=std::chrono::milliseconds(plan_->config.intervalMs);double budget=last_==std::chrono::steady_clock::time_point{}?double(plan_->config.intervalMs):std::clamp(std::chrono::duration<double,std::milli>(now-last_).count(),0.0,80.0);last_=now;next_=now+interval;const double speed=speed_==PlaybackSpeed::Quick?.65:speed_==PlaybackSpeed::Deliberate?1.5:1;const auto slice=std::chrono::steady_clock::now()+std::chrono::milliseconds(3);unsigned points=0;bool changed=false;while(active()&&budget>0&&points<plan_->config.pointBudget&&std::chrono::steady_clock::now()<slice){if(pauseMs_>0){const auto used=std::min(budget,pauseMs_);pauseMs_-=used;budget-=used;if(pauseMs_>0||budget<=0)break;}if(stroke_>=plan_->strokes.size())break;const auto& s=plan_->strokes[stroke_];if(!penOpen_){product::require(canvas.playBegin(s.style),"tom-playback-begin");if(!begun_){cursor_=s.points.front();point_=1;begun_=true;}product::require(canvas.playPoint(cursor_,true),"tom-playback-point");penOpen_=true;changed=true;++points;}if(point_>=s.points.size()){canvas.playEnd();if(s.fill)canvas.playFill(*s.fill);penOpen_=begun_=false;pauseMs_=s.pauseAfterMs*speed;++stroke_;continue;}const auto target=s.points[point_];const double dx=target.x-cursor_.x,dy=target.y-cursor_.y,length=std::hypot(dx,dy),msPerUnit=s.durationMs*speed/std::max(.1,s.travel),part=std::min(length,budget/msPerUnit);auto next=length>0?styled::Coordinate{cursor_.x+dx*part/length,cursor_.y+dy*part/length}:target;product::require(canvas.playPoint(next,false),"tom-playback-point");cursor_=next;budget-=std::max(.02,part*msPerUnit);++points;changed=true;if(part>=length)++point_;}return changed;}
